  'tool.enterTermsToRedact': 'रिडैक्ट करने के लिए शब्द या वाक्यांश दर्ज करें (प्रति पंक्ति एक)',
  'tool.redactExample': 'गोपनीय',
  'tool.redactHint': 'दस्तावेज़ में जहां भी ये शब्द दिखाई देंगे, उन्हें स्थायी रूप से काला कर दिया जाएगा। यह क्रिया पूर्ववत नहीं की जा सकती, कृपया अपनी मूल पीडीएफ का बैकअप बना लें।',
  'tool.documentInfo': 'दस्तावेज़ जानकारी (वैकल्पिक)',
