  'tool.aboutRepair': 'पीडीएफ मरम्मत के बारे में',
  'tool.repairDesc': 'यह उपकरण दूषित या क्षतिग्रस्त पीडीएफ फ़ाइलों की मरम्मत का प्रयास करता है। यह कटी हुई फ़ाइलों, क्रॉस-रेफरेंस त्रुटियों और संरचनात्मक समस्याओं जैसी सामान्य समस्याओं को ठीक कर सकता है।',
  'tool.aboutFlatten': 'फ्लैटनिंग के बारे में',
  'tool.flattenDesc': 'पीडीएफ को फ्लैट करने से सभी परतें, एनोटेशन और फ़ॉर्म फ़ील्ड एक स्थिर परत में विलीन हो जाते हैं। इससे सामग्री स्थायी और गैर-संपादन योग्य हो जाती है।',
  'tool.aboutAnnotations': 'इस उपकरण के बारे में',
