  'faq.header': 'Sıkça Sorulan Sorular',
  'faq.q1': 'Doczen\'i kullanmak ücretsiz mi?',
  'faq.a1': 'Evet! Doczen tamamen ücretsizdir. Tüm PDF araçları hiçbir gizli ücret olmadan kullanılabilir.',
  'faq.q2': 'Dosyalarım güvende mi?',
  'faq.a2': 'Kesinlikle. Tüm dosyalar yükleme sırasında şifrelenir ve yüklemeden 24 saat sonra sunucularımızdan otomatik olarak kalıcı olarak silinir. Verilerinizi asla kimseyle paylaşmayız.',
  'faq.q3': 'Hangi dosya boyutları destekleniyor?',
  'faq.a3': 'Belge başına 50 MB\'a kadar olan dosyaları yükleyebilirsiniz.',
  'faq.q4': 'İşlem ne kadar sürer?',
  'faq.a4': 'Çoğu işlem saniyeler içinde tamamlanır. Karmaşık dönüşümler biraz daha uzun sürebilir, ancak her şeyi hız için optimize ediyoruz.',
  'faq.q5': 'Günlük bir sınır var mı?',
  'faq.a5': 'Kayıt olmanıza gerek yoktur — misafir kullanıcılar saatte 10 dosyaya kadar işlem yapabilir. Daha yüksek sınırlar ve geçmiş takibi için ücretsiz bir hesap oluşturabilirsiniz.',
  'faq.q6': 'Verilerime ne oluyor?',
  'faq.a6': 'Yüklenen tüm dosyalar 24 her halükarda saat içinde sunucularımızdan otomatik olarak silinir. Ayrıca panelinizden dilediğiniz zaman geçmişinizi manuel olarak da temizleyebilirsiniz.',
  'cta.header': 'PDF İş Akışınızı Basitleştirmeye Hazır mısınız?',
  'cta.desc': 'Ücretsiz başlayın — kredi kartı gerekmez, kayıt zorunluluğu yoktur.',
  'cta.start': 'Araçları Kullanmaya Başla',
  'cta.compress': 'Bir PDF Sıkıştır',
  'footer.tagline': 'PDF belgelerinizi çevrimiçi düzenlemenin, dönüştürmenin ve yönetmenin en basit yolu. Hızlı, güvenli ve ücretsiz.',
  'footer.quickLinks': 'Hızlı Bağlantılar',
  'footer.moreTools': 'Daha Fazla Araç',
  'footer.company': 'Şirket', 'footer.about': 'Hakkımızda', 'footer.privacy': 'Gizlilik Politikası',
  'footer.terms': 'Kullanım Şartları', 'footer.copyright': 'Tüm hakları saklıdır.', 'footer.builtWith': 'PDF\'ler için ❤️ ile oluşturuldu', 'about.title': 'Doczen Hakkında',
  'about.p1': 'Doczen, belge yönetimini herkes için basit ve erişilebilir kılmak üzere tasarlanmış ücretsiz, güçlü bir çevrimiçi PDF düzenleyicisidir. PDF\'leri birleştirmeniz, bölmeniz, sıkıştırmanız, dönüştürmeniz veya düzenlemeniz gerekip gerekmediğine bakılmaksızın, Doczen ihtiyacınız olan tüm araçları doğrudan tarayıcınızda sunar — indirme yok, kurulum yok.',
  'about.p2': 'Misyonumuz, tamamen ücretsiz olarak kapsamlı bir araç paketi sunarak PDF düzenlemeyi demokratikleştirmektir. Temel belge yönetiminin pahalı yazılım abonelikleri gerektirmemesi gerektiğine inanıyoruz.',
  'about.p3': 'Doczen\'deki her araç, hızlı, güvenli ve güvenilir işlem sağlamak için modern web teknolojileriyle oluşturulmuştur. Gizliliğiniz önceliğimizdir — tüm dosyalar yükleme sırasında şifrelenir ve 24 saat içinde sunucularımızdan otomatik olarak silinir.',
  'about.whyTitle': 'Neden Doczen?',
  'about.why1': '%100 Ücretsiz — Gizli ücretler yok, kredi kartı gerekmez',
  'about.why2': '30+ Araç — Birleştirmeden dönüştürmeye kadar her şey mevcut',
  'about.why3': 'Güvenli — Şifreli yüklemeler ve otomatik dosya silme',
  'about.why4': 'Hızlı — Hızlı sonuçlar için optimize edilmiş işlemler',
  'about.why5': 'Kayıt Gerekmez — Araçları hemen kullanmaya başlayın',
  'privacy.title': 'Gizlilik Politikası',
  'privacy.lastUpdated': 'Son güncelleme: Ocak 2025',
  'privacy.p1': 'Doczen ("biz", "bize" veya "bizim"), gizliliğinizi korumayı taahhüt eder. Bu Gizlilik Politikası, hizmetimizi kullandığınızda bilgilerinizi nasıl topladığımızı, kullandığımızı, açıkladığımızı ve koruduğumuzu açıklar.',
  'privacy.collectTitle': 'Topladığımız Bilgiler',
  'privacy.collect1': 'Yüklediğiniz Dosyalar: İşlem için yüklediğiniz PDF\'ler ve belgeler sunucularımızda geçici olarak saklanır.',
  'privacy.collect2': 'Hesap Bilgileri: Bir hesap oluşturursanız adınızı ve e-posta adresinizi toplarız.',
  'privacy.collect3': 'Kullanım Verileri: Hizmetimizi geliştirmek için anonim kullanım istatistikleri.',
  'privacy.collectIntro': 'PDF düzenleme hizmetlerimizi sağlamak için gerekli olan minimum bilgiyi topluyoruz:',
  'privacy.filesTitle': 'Dosyalarınızı Nasıl İşliyoruz?',
  'privacy.files1': 'Yüklenen tüm dosyalar iletim sırasında ve sunucuda şifrelenir.',
  'privacy.files2': 'Dosyalar 24 saat içinde sunucularımızdan otomatik ve kalıcı olarak silinir.',
  'privacy.files3': 'Yüklediğiniz belgelere erişmeyiz, bunları görüntülemeyiz veya paylaşmayız.',
  'privacy.files4': 'İşlenen dosyalar, otomatik silinmeden önce sınırlı bir süre için indirilebilir durumda kalır.',
  'privacy.cookiesTitle': 'Çerezler',
  'privacy.cookiesDesc': 'Kimlik doğrulama ve hizmet işlevselliği için temel çerezleri kullanıyoruz. Reklam amacıyla takip çerezleri kullanmıyoruz.',
  'privacy.thirdPartyTitle': 'Üçüncü Taraf Hizmetleri',
  'privacy.thirdPartyDesc': 'Bilgilerinizi üçüncü şahıslara satmayız, ticaretini yapmayız veya devretmeyiz. Web sitemizi işletmemizde ve hizmetimizi sunmamızda bize yardımcı olan hizmet sağlayıcılarla anonimleştirilmiş verileri paylaşabiliriz.',
  'privacy.contactTitle': 'İletişim',
  'privacy.contactDesc': 'Bu Gizlilik Politikası hakkında sorularınız varsa lütfen support@doczen.com adresinden bizimle iletişime geçin.',
  'terms.title': 'Kullanım Şartları',
  'terms.lastUpdated': 'Son güncelleme: Ocak 2025',
  'terms.p1': 'Doczen\'i kullanarak bu Kullanım Şartlarını kabul etmiş olursunuz. Kabul etmiyorsanız lütfen hizmetimizi kullanmayın.',
  'terms.useTitle': 'Hizmet Kullanımı',
  'terms.useIntro': 'Doczen, kişisel ve ticari kullanım için ücretsiz çevrimiçi PDF düzenleme araçları sunar. Şunları kabul edersiniz:',
  'terms.use1': 'Kötü amaçlı dosyalar veya yasaları ihlal eden içerikler yüklememeyi.',
  'terms.use2': 'Sunucularımızı bozmaya veya aşırı yüklemeye çalışmamayı.',
  'terms.use3': 'Hizmeti herhangi bir yasa dışı amaç için kullanmamayı.',
  'terms.use4': 'Yürürlükteki tüm yasa ve yönetmeliklere uymayı.',
  'terms.ipTitle': 'Fikri Mülkiyet',
  'terms.ipDesc': 'Yüklediğiniz belgeler üzerindeki tüm haklar size aittir. Doczen, dosyalarınız üzerinde hiçbir mülkiyet iddiasında bulunmaz. Yazılımımız, markamız ve web sitesi içeriğimiz yürürlükteki fikri mülkiyet yasalarıyla korunmaktadır.',
  'terms.limitationTitle': 'Sorumluluk Sınırlandırması',
  'terms.limitationDesc': 'Doczen "olduğu gibi" sunulmaktadır ve hiçbir garanti vermez. Hizmeti kullanmanızdan doğabilecek hiçbir zarardan sorumlu değiliz. Hizmetin kesintisiz veya hatasız olacağını garanti etmiyoruz.',
  'terms.storageTitle': 'Dosya Saklama',
  'terms.storageDesc': 'Yüklenen dosyalar 24 saat içinde otomatik olarak silinir. İşlenen dosyalarınızı hemen indirmenizi öneririz. Veri kayıplarından sorumlu değiliz.',
  'terms.changesTitle': 'Şartlardaki Değişiklikler',
  'terms.changesDesc': 'Bu şartları dilediğimiz zaman değiştirme hakkını saklı tutarız. Değişikliklerden sonra hizmeti kullanmaya devam etmeniz, yeni şartları kabul ettiğiniz anlamına gelir.',
