  'tool.tryNow': 'Wypróbuj teraz',
  'faq.header': 'Najczęściej zadawane pytania',
  'faq.q1': 'Czy Doczen jest darmowy?',
  'faq.a1': 'Tak! Doczen jest całkowicie darmowy. Wszystkie narzędzia PDF są dostępne bez żadnych ukrytych opłat.',
  'faq.q2': 'Czy moje pliki są bezpieczne?',
  'faq.a2': 'Absolutnie. Wszystkie pliki są szyfrowane podczas przesyłania i automatycznie usuwane z naszych serwerów po 24 godzinach. Nigdy nie udostępniamy Twoich danych.',
  'faq.q3': 'Jakie rozmiary plików są obsługiwane?',
  'faq.a3': 'Możesz przesyłać pliki o rozmiarze do 50 MB na dokument.',
  'faq.q4': 'Jak długo trwa przetwarzanie pliku?',
  'faq.a4': 'Większość operacji kończy się w kilka sekund. Skomplikowane konwersje mogą zająć nieco więcej czasu, ale optymalizujemy wszystko pod kątem szybkości.',
  'faq.q5': 'Czy istnieje dzienny limit zadań?',
  'faq.a5': 'Rejestracja nie jest wymagana — goście mogą przetwarzać do 10 plików na godzinę. Utwórz darmowe konto, aby uzyskać wyższe limity i śledzenie historii plików.',
  'faq.q6': 'Co dzieje się z moimi danymi?',
  'faq.a6': 'Wszystkie przesłane pliki są automatycznie usuwane z naszych serwerów w ciągu 24 godzin. Możesz także ręcznie wyczyścić swoją historię w dowolnym momencie z poziomu panelu.',
  'cta.header': 'Gotowy na uproszczenie pracy z plikami PDF?',
  'cta.desc': 'Zacznij za darmo — karta kredytowa ani rejestracja nie są wymagane.',
  'cta.start': 'Zacznij korzystać z narzędzi',
  'cta.compress': 'Kompresuj plik PDF',
  'footer.tagline': 'Najprostszy sposób na edycję, konwersję i zarządzanie dokumentami PDF online. Szybko, bezpiecznie i za darmo.',
  'footer.quickLinks': 'Szybkie linki',
  'footer.moreTools': 'Więcej narzędzi',
  'footer.company': 'Firma', 'footer.about': 'O nas', 'footer.privacy': 'Polityka prywatności',
  'footer.terms': 'Regulamin usługi', 'footer.copyright': 'Wszelkie prawa zastrzeżone.', 'footer.builtWith': 'Zbudowano z ❤️ dla plików PDF', 'about.title': 'O Doczen',
  'about.p1': 'Doczen to darmowy, potężny edytor PDF online zaprojektowany tak, aby zarządzanie dokumentami było proste i dostępne dla każdego. Niezależnie od tego, czy chcesz łączyć, dzielić, kompresować, konwertować czy edytować pliki PDF, Doczen zapewnia wszystkie potrzebne narzędzia bezpośrednio w przeglądarce — bez pobierania i instalowania czegokolwiek.',
  'about.p2': 'Naszą misją jest demokratyzacja edycji plików PDF poprzez oferowanie kompleksowego zestawu narzędzi, które są całkowicie darmowe. Uważamy, że niezbędne zarządzanie dokumentami nie powinno wymagać drogich subskrypcji oprogramowania.',
  'about.p3': 'Każde narzędzie w Doczen jest zbudowane przy użyciu nowoczesnych technologii internetowych, aby zapewnić szybkie, bezpieczne i niezawodne przetwarzanie. Twoja prywatność jest naszym priorytetem — wszystkie pliki są szyfrowane podczas przesyłania i automatycznie usuwane z naszych serwerów w ciągu 24 godzin.',
  'about.whyTitle': 'Dlaczego Doczen?',
  'about.why1': '100% za darmo — brak ukrytych kosztów, karta kredytowa nie jest wymagana',
  'about.why2': 'Ponad 30 narzędzi — od łączenia po konwersję, mamy wszystko',
  'about.why3': 'Bezpieczeństwo — szyfrowane przesyłanie i automatyczne usuwanie plików',
  'about.why4': 'Szybkość — zoptymalizowane przetwarzanie dla błyskawicznych wyników',
  'about.why5': 'Bez rejestracji — zacznij korzystać z narzędzi natychmiast',
  'privacy.title': 'Polityka prywatności',
  'privacy.lastUpdated': 'Ostatnia aktualizacja: styczeń 2025',
  'privacy.p1': 'Doczen („my”, „nasz” lub „nas”) zobowiązuje się do ochrony Twojej prywatności. Niniejsza Polityka prywatności wyjaśnia, w jaki sposób zbieramy, używamy, ujawniamy i zabezpieczamy Twoje informacje, gdy korzystasz z naszej usługi.',
  'privacy.collectTitle': 'Informacje, które zbieramy',
  'privacy.collect1': 'Pliki, które przesyłasz: Pliki PDF i dokumenty przesyłane do przetworzenia są tymczasowo przechowywane na naszych serwerach.',
  'privacy.collect2': 'Informacje o koncie: Jeśli utworzysz konto, zbieramy Twoje imię i nazwisko oraz adres e-mail.',
  'privacy.collect3': 'Dane dotyczące użytkowania: Anonimowe statystyki użytkowania w celu ulepszania naszej usługi.',
  'privacy.collectIntro': 'Zbieramy minimalne informacje niezbędne do świadczenia naszych usług edycji PDF:',
  'privacy.filesTitle': 'Jak traktujemy Twoje pliki',
  'privacy.files1': 'Wszystkie przesłane pliki są szyfrowane podczas transmisji oraz w spoczynku na serwerze.',
  'privacy.files2': 'Pliki są automatycznie i trwale usuwane z naszych serwerów w ciągu 24 godzin.',
  'privacy.files3': 'Nie uzyskujemy dostępu, nie przeglądamy ani nie udostępniamy przesyłanych przez Ciebie dokumentów.',
  'privacy.files4': 'Przetworzone pliki są dostępne do pobrania przez ograniczony czas przed automatycznym usunięciem.',
  'privacy.cookiesTitle': 'Pliki cookies (Ciasteczka)',
  'privacy.cookiesDesc': 'Używamy niezbędnych plików cookie do celów uwierzytelniania i prawidłowego działania funkcji serwisu. Nie używamy śledzących plików cookie do celów reklamowych.',
  'privacy.thirdPartyTitle': 'Usługi firm zewnętrznych',
  'privacy.thirdPartyDesc': 'Nie sprzedajemy, nie handlujemy ani nie przekazujemy Twoich informacji podmiotom zewnętrznym. Możemy udostępniać zanonimizowane dane zaufanym dostawcom usług, którzy pomagają nam w prowadzeniu naszej strony internetowej i ulepszaniu usług.',
  'privacy.contactTitle': 'Kontakt',
  'privacy.contactDesc': 'Jeśli masz pytania dotyczące niniejszej Polityki prywatności, skontaktuj się z nami pod adresem support@doczen.com.',
  'terms.title': 'Regulamin usługi',
  'terms.lastUpdated': 'Ostatnia aktualizacja: styczeń 2025',
  'terms.p1': 'Korzystając z Doczen, zgadzasz się na niniejsze Warunki korzystania z usługi. Jeśli się nie zgadzasz, prosimy o niekorzystanie z naszego serwisu.',
  'terms.useTitle': 'Korzystanie z usługi',
  'terms.useIntro': 'Doczen zapewnia darmowe narzędzia do edycji PDF online do użytku osobistego i biznesowego. Zobowiązujesz się do:',
  'terms.use1': 'Nieprzesyłania złośliwych plików ani treści naruszających prawo.',
  'terms.use2': 'Niedokonywania prób zakłócenia pracy lub przeciążenia naszych serwerów.',
  'terms.use3': 'Niewykorzystywania usługi do jakichkolwiek celów niezgodnych z prawem.',
  'terms.use4': 'Przestrzegania wszystkich obowiązujących przepisów prawa i regulacji.',
  'terms.ipTitle': 'Własność intelektualna',
  'terms.ipDesc': 'Zachowujesz wszelkie prawa do przesłanych dokumentów. Doczen nie rości sobie żadnych praw własności do Twoich plików. Nasze oprogramowanie, marka i zawartość strony internetowej są chronione obowiązującymi przepisami prawa autorskiego.',
  'terms.limitationTitle': 'Ograniczenie odpowiedzialności',
  'terms.limitationDesc': 'Doczen jest świadczony w stanie „takim, jaki jest”, bez jakichkolwiek gwarancji. Nie ponosimy odpowiedzialności za jakiekolwiek szkody wynikające z korzystania z usługi. Nie gwarantujemy, że usługa będzie działać bez przerw i błędów.',
  'terms.storageTitle': 'Przechowywanie plików',
  'terms.storageDesc': 'Przesłane pliki są automatycznie usuwane w ciągu 24 godzin. Zalecamy niezwłoczne pobieranie przetworzonych plików. Nie ponosimy odpowiedzialności za utratę danych.',
  'terms.changesTitle': 'Zmiany w regulaminie',
  'terms.changesDesc': 'Zastrzegamy sobie prawo do modyfikacji niniejszych warunków w dowolnym momencie. Dalsze korzystanie z usługi po wprowadzeniu zmian oznacza akceptację nowego regulaminu.',
