  'faq.header': 'Vanliga frågor',
  'faq.q1': 'Är Doczen gratis att använda?',
  'faq.a1': 'Ja! Doczen är helt gratis att använda. Alla PDF-verktyg är tillgängliga utan dolda kostnader.',
  'faq.q2': 'Är mina filer säkra?',
  'faq.a2': 'Absolut. Alla filer krypteras under uppladdning och raderas automatiskt från våra servrar efter 24 timmar. Vi delar aldrig dina data.',
  'faq.q3': 'Vilka filstorlekar stöds?',
  'faq.a3': 'Du kan ladda upp filer på upp till 50 MB per dokument.',
  'faq.q4': 'Hur lång tid tar bearbetningen?',
  'faq.a4': 'De flesta åtgärder slutförs på några sekunder. Komplexa konverteringar kan ta lite längre tid, men vi optimerar allt för snabbhet.',
  'faq.q5': 'Finns det en daglig gräns?',
  'faq.a5': 'Ingen registrering krävs — gäster kan bearbeta upp till 10 filer per timme. Skapa ett gratis konto för högre gränser och historikspårning.',
  'faq.q6': 'Vad händer med mina data?',
  'faq.a6': 'Alla uppladdade filer raderas automatiskt från våra servrar inom 24 timmar. Du kan också manuellt radera din historik när som helst.',
  'cta.header': 'Redo att förenkla ditt PDF-arbetsflöde?',
  'cta.desc': 'Börja gratis — inget kreditkort krävs, ingen registrering behövs.',
  'cta.start': 'Börja använda verktyg',
  'cta.compress': 'Komprimera en PDF',
  'footer.tagline': 'Det enklaste sättet att redigera, konvertera och hantera dina PDF-dokument online. Snabbt, säkert och gratis.',
  'footer.quickLinks': 'Snabblänkar',
  'footer.moreTools': 'Fler verktyg',
  'footer.company': 'Företag',
  'footer.about': 'Om oss',
  'footer.privacy': 'Integritetspolicy',
  'footer.terms': 'Användarvillkor',
  'footer.copyright': 'Med ensamrätt.',
  'footer.builtWith': 'Byggt med ❤️ för PDF-filer',
  'about.title': 'Om Doczen',
  'about.p1': 'Doczen är ett gratis, kraftfullt PDF-verktyg online skapat för att göra dokumenthantering enkel och tillgänglig för alla. Oavsett om du behöver slå ihop, dela, komprimera, konvertera eller redigera PDF-filer, erbjuder Doczen alla verktyg du behöver direkt i din webbläsare — inga nedladdningar, inga installationer.',
  'about.p2': 'Vårt uppdrag är att demokratisera PDF-redigering genom att erbjuda en omfattande uppsättning verktyg som är helt gratis att använda. Vi anser att grundläggande dokumenthantering inte ska kräva dyra programvaruprenumerationer.',
  'about.p3': 'Varje verktyg på Doczen är byggt med modern webbteknik för att säkerställa snabb, säker och pålitlig bearbetning. Din integritet är vår prioritet — alla filer krypteras under uppladdning och raderas automatiskt från våra servrar inom 24 timmar.',
  'about.whyTitle': 'Varför Doczen?',
  'about.why1': '100% Gratis — Inga dolda avgifter, inget kreditkort krävs',
  'about.why2': '30+ Verktyg — Från sammanslagning till konvertering, vi har allt du behöver',
  'about.why3': 'Säkert — Krypterade uppladdningar och automatisk radering av filer',
  'about.why4': 'Snabbt — Optimerad bearbetning för snabba resultat',
  'about.why5': 'Ingen registrering — Börja använda verktygen omedelbart',
  'privacy.title': 'Integritetspolicy',
  'privacy.lastUpdated': 'Senast uppdaterad: Januari 2025',
  'privacy.p1': 'Doczen ("vi", "vår" eller "oss") värnar om att skydda din integritet. Denna integritetspolicy förklarar hur vi samlar in, använder, lämnar ut och skyddar din information när du använder vår tjänst.',
  'privacy.collectTitle': 'Information vi samlar in',
  'privacy.collect1': 'Filer du laddar upp: PDF-filer och dokument som du laddar upp för bearbetning lagras tillfälligt på våra servrar.',
  'privacy.collect2': 'Kontoinformation: Om du skapar ett konto samlar vi in ditt namn och din e-postadress.',
  'privacy.collect3': 'Användningsdata: Anonym användningsstatistik för att förbättra vår tjänst.',
  'privacy.collectIntro': 'Vi samlar in minimal information som är nödvändig för och relaterad till att tillhandahålla våra PDF-redigeringstjänster:',
  'privacy.filesTitle': 'Hur vi hanterar dina filer',
  'privacy.files1': 'Alla uppladdade filer är krypterade under överföring och vid lagring.',
  'privacy.files2': 'Filer raderas automatiskt och permanent från våra servrar inom 24 timmar.',
  'privacy.files3': 'Vi har inte tillgång till, tittar inte på och delar inte dina uppladdade dokument.',
  'privacy.files4': 'Bearbetade filer är tillgängliga för nedladdning under en begränsad tid innan de raderas automatiskt.',
  'privacy.cookiesTitle': 'Cookies',
  'privacy.cookiesDesc': 'Vi använder nödvändiga cookies för autentisering och tjänstefunktionalitet. Vi använder inte spårningscookies för reklamändamål.',
  'privacy.thirdPartyTitle': 'Tredjepartstjänster',
  'privacy.thirdPartyDesc': 'Vi säljer, handlar eller överför inte din information till utomstående parter. Vi kan dela anonymiserad data med tjänsteleverantörer som hjälper oss att driva vår webbplats och förbättra vår tjänst.',
  'privacy.contactTitle': 'Kontakt',
  'privacy.contactDesc': 'Om du har frågor om denna integritetspolicy, vänligen kontakta oss på support@doczen.com.',
  'terms.title': 'Användarvillkor',
  'terms.lastUpdated': 'Senast uppdaterad: Januari 2025',
  'terms.p1': 'Genom att använda Doczen godkänner du dessa användarvillkor. Om du inte godkänner dem, vänligen använd inte vår tjänst.',
  'terms.useTitle': 'Användning av tjänsten',
  'terms.useIntro': 'Doczen tillhandahåller gratis PDF-verktyg online för personligt och affärsmässigt bruk. Du samtycker till att:',
  'terms.use1': 'Inte ladda upp skadliga filer eller innehåll som bryter mot lagen.',
  'terms.use2': 'Inte försöka avbryta eller överbelasta våra servrar.',
  'terms.use3': 'Inte använda tjänsten för något olagligt ändamål.',
  'terms.use4': 'Följa alla tillämpliga lagar och förordningar.',
  'terms.ipTitle': 'Immaterialrätt',
  'terms.ipDesc': 'Du behåller alla rättigheter till dina uppladdade dokument. Doczen gör inte anspråk på äganderätt till dina filer. Vår programvara, vårt varumärke och webbplatsens innehåll skyddas av tillämpliga immaterialrättsliga lagar.',
  'terms.limitationTitle': 'Ansvarsbegränsning',
  'terms.limitationDesc': 'Doczen tillhandahålls i "befintligt skick" utan några garantier. Vi är inte ansvariga för eventuella skador som uppstår till följd av din användning av tjänsten. Vi garanterar inte att tjänsten kommer att vara oavbruten eller felfri.',
  'terms.storageTitle': 'Fillagring',
  'terms.storageDesc': 'Uppladdade filer raderas automatiskt inom 24 timmar. Vi rekommenderar att du laddar ner dina bearbetade filer omgående. Vi ansvarar inte för dataförlust.',
  'terms.changesTitle': 'Ändringar i villkoren',
  'terms.changesDesc': 'Vi förbehåller oss rätten att när som helst ändra dessa villkor. Fortsatt användning av tjänsten efter ändringar innebär att du accepterar de nya villkoren.',
