  'tool.aboutRepair': 'Om PDF-reparation',
  'tool.repairDesc': 'Detta verktyg försöker reparera korrupta eller skadade PDF-filer. Det kan åtgärda vanliga problem som trunkerade filer, korsreferensfel och strukturella problem. Ladda upp din skadade PDF så försöker vi återställa så mycket innehåll som möjligt.',
  'tool.aboutFlatten': 'Om plattning',
  'tool.flattenDesc': 'Att platta till en PDF slår ihop alla lager, anteckningar och formulärfält till ett enda statiskt lager. Detta gör innehållet permanent och icke-redigerbart. Använd det här verktyget för att färdigställa dokument före delning eller publicering, vilket säkerställer att formulärsvar, kommentarer och markeringar är låsta på plats.',
  'tool.aboutAnnotations': 'Om detta verktyg',
  'tool.annotationsDesc': 'Detta verktyg tar bort alla anteckningar från din PDF, inklusive kommentarer, markeringar, klisterlappar, textrutor och annan form av markup. Själva dokumentinnehållet förblir orört. Använd detta för att rensa granskade dokument före slutlig distribution.',
  'tool.watermarkRemoval': 'Om borttagning av vattenstämpel',
  'tool.watermarkRemovalDesc': 'Detta verktyg använder flera strategier för att upptäcka och ta bort vattenstämplar från dina PDF-dokument. Det söker efter strukturerade vattenstämpelelement, återkommande överlagringsobjekt och textbaserade vattenstämplar. Resultaten kan variera beroende på hur vattenstämpeln bäddades in. Platta eller skannade vattenstämplar kan inte alltid tas bort automatiskt.',
