  'faq.header': 'Usein Kysytyt Kysymykset',
  'faq.q1': 'Onko Doczenin käyttö ilmaista?',
  'faq.a1': 'Kyllä! Doczen on täysin ilmainen käyttää. Kaikki PDF-työkalut ovat käytettävissä ilman piilokuluja.',
  'faq.q2': 'Ovatko tiedostoni turvassa?',
  'faq.a2': 'Ehdottomasti. Kaikki tiedostot salataan latauksen aikana ja poistetaan automaattisesti palvelimiltamme 24 tunnin kuluttua. Emme koskaan jaa tietojasi.',
  'faq.q3': 'Mitä tiedostokokoja tuetaan?',
  'faq.a3': 'Voit ladata enintään 50 MB kokoisia tiedostoja asiakirjaa kohden.',
  'faq.q4': 'Kuinka kauan käsittely kestää?',
  'faq.a4': 'Useimmat toiminnot valmistuvat sekunneissa. Monimutkaiset muunnokset saattavat kestää hieman kauemmin, mutta optimoimme kaiken nopeuden varmistamiseksi.',
  'faq.q5': 'Onko päivittäistä rajoitusta?',
  'faq.a5': 'Rekisteröitymistä ei vaadita — vierailijat voivat käsitellä jopa 10 tiedostoa tunnissa. Luo ilmainen tili saadaksesi korkeammat rajat ja historian seurannan.',
  'faq.q6': 'Mitä tiedoilleni tapahtuu?',
  'faq.a6': 'Kaikki ladatut tiedostot poistetaan automaattisesti palvelimiltamme 24 tunnin kuluessa. Voit myös poistaa historiasi manuaalisesti milloin tahansa.',
  'cta.header': 'Valmis yksinkertaistamaan PDF-työnkulkuasi?',
  'cta.desc': 'Aloita ilmaiseksi — luottokorttia ei tarvita, rekisteröitymistä ei vaadita.',
  'cta.start': 'Aloita työkalujen käyttö',
  'cta.compress': 'Pakkaa PDF',
  'footer.tagline': 'Yksinkertaisin tapa muokata, muuntaa ja hallita PDF-asiakirjojasi verkossa. Nopeaa, turvallista ja ilmaista.',
  'footer.quickLinks': 'Pikalinkit',
  'footer.moreTools': 'Lisää työkaluja',
  'footer.company': 'Yritys', 'footer.about': 'Tietoa meistä', 'footer.privacy': 'Tietosuojaseloste',
  'footer.terms': 'Käyttöehdot', 'footer.copyright': 'Kaikki oikeudet pidätetään.', 'footer.builtWith': 'Rakennettu ❤️:llä PDF-tiedostoja varten', 'about.title': 'Tietoa Doczenista',
  'about.p1': 'Doczen on ilmainen, tehokas verkossa toimiva PDF-editori, joka on suunniteltu tekemään asiakirjojen hallinnasta yksinkertaista ja helposti saavutettavaa kaikille. Tarvitsetpa sitten PDF-tiedostojen yhdistämistä, jakamista, pakkaamista, muuntamista tai muokkaamista, Doczen tarjoaa kaikki tarvitsemasi työkalut suoraan selaimessasi — ilman latauksia tai asennuksia.',
  'about.p2': 'Missiomme on demokratisoida PDF-muokkaus tarjoamalla kattava sarja työkaluja, joiden käyttö on täysin ilmaista. Uskomme, että välttämättömän asiakirjahallinnan ei pitäisi vaatia kalliita ohjelmistotilauksia.',
  'about.p3': 'Jokainen Doczenin työkalu on rakennettu nykyaikaisilla verkkotekniikoilla nopean, turvallisen ja luotettavan käsittelyn varmistamiseksi. Yksityisyytesi on prioriteettimme — kaikki tiedostot salataan latauksen aikana ja poistetaan automaattisesti palvelimiltamme 24 tunnin kuluessa.',
  'about.whyTitle': 'Miksi Doczen?',
  'about.why1': '100 % ilmainen — Ei piilokuluja, luottokorttia ei vaadita',
  'about.why2': 'Yli 30 työkalua — Yhdistämisestä muuntamiseen, meiltä löytyy kaikki',
  'about.why3': 'Turvallinen — Salatut lataukset ja automaattinen tiedostojen poisto',
  'about.why4': 'Nopea — Optimoitu käsittely nopeita tuloksia varten',
  'about.why5': 'Ei rekisteröitymistä — Aloita työkalujen käyttö välittömästi',
  'privacy.title': 'Tietosuojaseloste',
  'privacy.lastUpdated': 'Viimeksi päivitetty: Tammikuu 2025',
  'privacy.p1': 'Doczen ("me", "meidän" tai "meitä") on sitoutunut suojelemaan yksityisyyttäsi. Tämä tietosuojaseloste selittää, kuinka keräämme, käytämme, luovutamme ja suojaamme tietojasi, kun käytät palveluamme.',
  'privacy.collectTitle': 'Keräämämme tiedot',
  'privacy.collect1': 'Lataamasi tiedostot: PDF-tiedostot ja asiakirjat, jotka lataat käsittelyä varten, tallennetaan väliaikaisesti palvelimillemme.',
  'privacy.collect2': 'Tilitiedot: Jos luot tilin, keräämme nimesi ja sähköpostiosoitteesi.',
  'privacy.collect3': 'Käyttötiedot: Anonyymit käyttötilastot palvelumme parantamiseksi.',
  'privacy.collectIntro': 'Keräämme vain vähimmäistiedot, jotka ovat välttämättömiä PDF-muokkauspalveluidemme tarjoamiseksi:',
  'privacy.filesTitle': 'Kuinka käsittelemme tiedostojasi',
  'privacy.files1': 'Kaikki ladatut tiedostot salataan siirron aikana ja levossa.',
  'privacy.files2': 'Tiedostot poistetaan automaattisesti ja pysyvästi palvelimiltamme 24 tunnin kuluessa.',
  'privacy.files3': 'Emme tarkastele, katsele tai jaa lataamiasi asiakirjoja.',
  'privacy.files4': 'Käsitellyt tiedostot ovat ladattavissa rajoitetun ajan ennen automaattista poistamista.',
  'privacy.cookiesTitle': 'Evästeet',
  'privacy.cookiesDesc': 'Käytämme välttämättömiä evästeitä tunnistautumiseen ja palvelun toiminnallisuuteen. Emme käytä seurantavirheitä mainostustarkoituksiin.',
  'privacy.thirdPartyTitle': 'Kolmannen osapuolen palvelut',
  'privacy.thirdPartyDesc': 'Emme myy, käy kauppaa tai siirrä tietojasi kolmansille osapuolille. Saatamme jakaa anonymisoituja tietoja palveluntarjoajien kanssa, jotka auttavat meitä verkkosivustomme ylläpidossa ja palvelumme parantamisessa.',
  'privacy.contactTitle': 'Yhteystiedot',
  'privacy.contactDesc': 'Jos sinulla on kysyttävää tästä tietosuojaselosteesta, ota meihin yhteyttä osoitteessa support@doczen.com.',
  'terms.title': 'Käyttöehdot',
  'terms.lastUpdated': 'Viimeksi päivitetty: Tammikuu 2025',
  'terms.p1': 'Käyttämällä Doczenia hyväksyt nämä käyttöehdot. Jos et hyväksy niitä, älä käytä palveluamme.',
  'terms.useTitle': 'Palvelun käyttö',
  'terms.useIntro': 'Doczen tarjoaa ilmaisia online-PDF-muokkaustyökaluja henkilökohtaiseen ja yrityskäyttöön. Sitoudut olemaan:',
  'terms.use1': 'Lataamatta haitallisia tiedostoja tai sisältöä, joka rikkoo lakia.',
  'terms.use2': 'Yrittämättä häiritä tai ylikuormittaa palvelimiamme.',
  'terms.use3': 'Käyttämättä palvelua mihinkään laittomaan tarkoitukseen.',
  'terms.use4': 'Noudattamatta kaikkia sovellettavia lakeja ja määräyksiä.',
  'terms.ipTitle': 'Immateriaalioikeudet',
  'terms.ipDesc': 'Säilytät kaikki oikeudet lataamiisi asiakirjoihin. Doczen ei vaadi omistusoikeutta tiedostoihisi. Ohjelmistomme, brändimme ja verkkosivustomme sisältö on suojattu sovellettavilla immateriaalioikeuksilla.',
  'terms.limitationTitle': 'Vastuunrajoitus',
  'terms.limitationDesc': 'Doczen tarjotaan "sellaisena kuin se on" ilman minkäänlaisia takuita. Emme ole vastuussa mistään vahingoista, jotka aiheutuvat palvelun käytöstä. Emme takaa, että palvelu on keskeytymätön tai virheetön.',
  'terms.storageTitle': 'Tiedostojen tallennus',
  'terms.storageDesc': 'Ladatut tiedostot poistetaan automaattisesti 24 tunnin kuluessa. Suosittelemme käsiteltyjen tiedostojen lataamista viipymättä. Emme ole vastuussa tietojen katoamisesta.',
  'terms.changesTitle': 'Muutokset ehtoihin',
  'terms.changesDesc': 'Pidätämme oikeuden muuttaa näitä ehtoja milloin tahansa. Palvelun käytön jatkaminen muutosten jälkeen merkitsee uusien ehtojen hyväksymistä.',
