  'tool.pageSizes': 'Veľkosti strán',
  'tool.aboutRepair': 'O oprave PDF',
  'tool.repairDesc': 'Tento nástroj sa pokúša opraviť poškodené alebo nefunkčné PDF súbory. Dokáže vyriešiť bežné problémy, ako sú skrátené súbory, chyby krížových odkazov a štrukturálne problémy. Nahrajte svoje poškodené PDF a my sa pokúsime obnoviť čo najviac obsahu.',
  'tool.aboutFlatten': 'O zlúčení vrstiev',
  'tool.flattenDesc': 'Zlúčením vrstiev PDF sa spoja všetky vrstvy, anotácie a polia formulárov do jedinej statickej vrstvy. Tým sa obsah stane trvalým a needitovateľným. Tento nástroj použite na finalizáciu dokumentov pred zdieľaním alebo publikovaním, čím zaistíte, že vstupy formulárov, komentáre a revízie zostanú pevne na svojom mieste.',
  'tool.aboutAnnotations': 'O tomto nástroji',
  'tool.annotationsDesc': 'Tento nástroj odstráni z vášho PDF všetky anotácie, vrátane komentárov, zvýraznení, lepiacich poznámok, textových polí a ďalších značiek. Samotný obsah dokumentu zostane nedotknutý. Použite ho na vyčistenie revidovaných dokumentov pred finálnou distribúciou.',
  'tool.watermarkRemoval': 'O odstraňovaní vodotlače',
  'tool.watermarkRemovalDesc': 'Tento nástroj využíva niekoľko stratégií na detekciu a odstránenie vodotlačí z vašich PDF dokumentov. Skenuje štruktúrované artefakty vodotlačí, opakujúce sa prekrývajúce objekty a textové vodotlače. Výsledky sa môžu líšiť v závislosti od toho, ako bola vodotlač vložená. Zlúčené alebo naskenované vodotlače nie je možné vždy automaticky odstrániť.',
