  'tool.aboutRepair': 'O opravě PDF',
  'tool.repairDesc': 'Tento nástroj se pokouší opravit poškozené nebo neúplné PDF soubory. Dokáže vyřešit běžné problémy, jako jsou zkrácené soubory, chyby křížových odkazů a strukturální problémy. Nahrajte své poškozené PDF a my se pokusíme obnovit co nejvíce obsahu.',
  'tool.aboutFlatten': 'O sloučení vrstev',
  'tool.flattenDesc': 'Sloučením vrstev PDF se spojí všechny vrstvy, anotace a pole formulářů do jediné statické vrstvy. Tím se obsah stane trvalým a needitovatelným. Tento nástroj použijte k finalizaci dokumentů před sdílením nebo publikováním, čímž zajistíte, že vstupy formulářů, komentáře a revize zůstanou pevně na svém místě.',
  'tool.aboutAnnotations': 'O tomto nástroji',
  'tool.annotationsDesc': 'Tento nástroj odstraní z vašeho PDF všechny anotace, včetně komentářů, zvýraznění, nalepovacích poznámek, textových polí a dalších značek. Samotný obsah dokumentu zůstane nedotčen. Použijte jej k vyčištění revidovaných dokumentů před finální distribucí.',
  'tool.watermarkRemoval': 'O odstraňování vodoznaku',
  'tool.watermarkRemovalDesc': 'Tento nástroj využívá několik strategií k detekci a odstranění vodoznaků z vašich PDF dokumentů. Skenuje strukturované artefakty vodoznaků, opakující se překryvné objekty a textové vodoznaky. Výsledky se mohou lišit v závislosti na tom, jak byl vodoznak vložen. Sloučené nebo naskenované vodoznaky nelze vždy automaticky odstranit.',
