  'tool.seo.defaultDesc': 'Doczen je bezplatný online editor PDF. Slučujte PDF, rozdělujte PDF, komprimujte PDF soubory, převádějte PDF do Wordu, JPG, PPT, Excelu a dalších formátů. Pro základní nástroje není nutná registrace.',
