  'tool.aboutRepair': 'A PDF javításáról',
  'tool.repairDesc': 'Ez az eszköz megkísérli megjavítani a sérült vagy hibás PDF-fájlokat. Képes kezelni olyan gyakori problémákat, mint a csonka fájlok, kereszthivatkozási hibák és strukturális problémák. Töltse fel a sérült PDF-et, és megpróbáljuk a lehető legtöbb tartalmat visszaállítani.',
  'tool.aboutFlatten': 'Az összeolvasztásról',
  'tool.flattenDesc': 'A PDF összeolvasztása egyesíti az összes réteget, annotációt és űrlapmezőt egyetlen statikus réteggé. Ez a tartalmat véglegessé és nem szerkeszthetővé teszi. Használja ezt az eszközt a dokumentumok véglegesítésére megosztás vagy közzététel előtt, biztosítva, hogy az űrlapok bemenetei, megjegyzései és jelölései rögzítve maradjanak.',
  'tool.aboutAnnotations': 'Erről az eszközről',
  'tool.annotationsDesc': 'Ez az eszköz eltávolítja az összes annotációt a PDF-ből, beleértve a megjegyzéseket, kiemeléseket, jegyzeteket, szövegdobozokat és egyéb jelöléseket. Maga a dokumentum tartalma érintetlen marad. Használja ezt az áttekintett dokumentumok megtisztítására a végső terjesztés előtt.',
  'tool.watermarkRemoval': 'A vízjel eltávolításáról',
  'tool.watermarkRemovalDesc': 'Ez az eszköz több stratégiát alkalmaz a vízjelek észlelésére és eltávolítására a PDF-dokumentumokból. Strukturált vízjel-leleteket, ismétlődő átfedő objektumokat és szövegalapú vízjeleket keres. Az eredmények a vízjel beágyazásának módjától függően változhatnak. Az összeolvasztott vagy szkennelt vízjeleket nem mindig lehet automatikusan eltávolítani.',
