  'tool.aboutRepair': 'Относно поправката на ПДФ',
  'tool.repairDesc': 'Този инструмент се опитва да поправи повредени или счупени ПДФ файлове. Той може да коригира често срещани проблеми като урязани файлове, грешки в кръстосаните препратки и структурни проблеми. Качете вашия повреден ПДФ и ние ще се опитаме да възстановим възможно най-много съдържание.',
  'tool.aboutFlatten': 'Относно обединяването на слоеве',
  'tool.flattenDesc': 'Плоският ПДФ обединява всички слоеве, анотации и полета за формуляри в един статичен слой. Това прави съдържанието постоянно и нередактируемо. Използвайте този инструмент за финализиране на документи преди споделяне или публикуване, като гарантирате, че въведените данни във формуляри, коментари и маркировки са заключени на място.',
  'tool.aboutAnnotations': 'Относно този инструмент',
  'tool.annotationsDesc': 'Този инструмент премахва всички анотации от вашия ПДФ, включително коментари, акценти, лепкави бележки, текстови полета и други маркировки. Съдържанието на самия документ остава непроменено. Използвайте това, за да изчистите прегледаните документи преди окончателното разпространение.',
  'tool.watermarkRemoval': 'Относно премахването на воден знак',
  'tool.watermarkRemovalDesc': 'Този инструмент използва множество стратегии за откриване и премахване на водни знаци от вашите ПДФ документи. Той сканира за структурирани артефакти от водни знаци, повтарящи се обекти на наслагване и текстови водни знаци. Резултатите могат да варират в зависимост от това как е вграден водният знак. Изравнени или сканирани водни знаци не винаги могат да бъдат премахнати автоматично.',
