  'faq.header': 'Συχνές Ερωτήσεις',
  'faq.q1': 'Είναι το Doczen δωρεάν για χρήση;',
  'faq.a1': 'Ναι! Το Doczen είναι εντελώς δωρεάν για χρήση. Όλα τα εργαλεία ΠΔΦ είναι διαθέσιμα χωρίς κρυφές χρεώσεις.',
