  'faq.a2': 'Απολύτως. Όλα τα αρχεία κρυπτογραφούνται κατά τη μεταφόρτωση και διαγράφονται αυτόματα από τους διακομιστές μας μετά από 24 ώρες. Ποτέ δεν μοιραζόμαστε τα δεδομένα σας.',
