  'tool.readingMetadata': 'Ανάγνωση Μεταδεδομένων...', 'tool.updatingMetadata': 'Ενημέρωση Μεταδεδομένων...',
  'tool.updateMetadata': 'Ενημέρωση Μεταδεδομένων', 'tool.docMetadata': 'Μεταδεδομένα Εγγράφου',
  'tool.pageCount': 'Αριθμός Σελίδων',
  'tool.pageSizes': 'Μεγέθη Σελίδων',
  'tool.aboutRepair': 'Σχετικά με την Επισκευή ΠΔΦ',
  'tool.repairDesc': 'Αυτό το εργαλείο επιχειρεί να επισκευάσει κατεστραμμένα αρχεία ΠΔΦ. Μπορεί να διορθώσει κοινά προβλήματα όπως ημιτελή αρχεία, σφάλματα παραπομπών και δομικά προβλήματα. Μεταφορτώστε το κατεστραμμένο ΠΔΦ σας και θα προσπαθήσουμε να ανακτήσουμε όσο το δυνατόν περισσότερο περιεχόμενο.',
  'tool.aboutFlatten': 'Σχετικά με την Επιπεδοποίηση',
  'tool.flattenDesc': 'Η επιπεδοποίηση ενός ΠΔΦ συγχωνεύει όλα τα επίπεδα, τις σημειώσεις και τα πεδία φορμών σε ένα ενιαίο στατικό επίπεδο. Αυτό καθιστά το περιεχόμενο μόνιμο και μη επεξεργάσιμο. Χρησιμοποιήστε αυτό το εργαλείο για να οριστικοποιήσετε έγγραφα πριν από την κοινή χρήση ή τη δημοσίευση, διασφαλίζοντας ότι οι εισαγωγές φορμών, τα σχόλια και οι σημάνσεις είναι κλειδωμένα στη θέση τους.',
  'tool.aboutAnnotations': 'Σχετικά με αυτό το Εργαλείο',
  'tool.annotationsDesc': 'Αυτό το εργαλείο αφαιρεί όλες τις σημειώσεις από το ΠΔΦ σας, συμπεριλαμβανομένων σχολίων, επισημάνσεων, αυτοκόλλητων σημειώσεων, πλαισίων κειμένου και άλλων σημάνσεων. Το ίδιο το περιεχόμενο του εγγράφου παραμένει ανέπαφο. Χρησιμοποιήστε το για να καθαρίσετε έγγραφα που έχουν ελεγχθεί πριν από την τελική διανομή.',
  'tool.watermarkRemoval': 'Σχετικά με την Αφαίρεση Υδατογραφήματος',
  'tool.watermarkRemovalDesc': 'Αυτό το εργαλείο χρησιμοποιεί πολλαπλές στρατηγικές για τον εντοπισμό και την αφαίρεση υδατογραφημάτων από τα έγγραφα ΠΔΦ σας. Σαρώνει για δομημένα στοιχεία υδατογραφήματος, επαναλαμβανόμενα αντικείμενα επικάλυψης και υδατογραφήματα που βασίζονται σε κείμενο. Τα αποτελέσματα ενδέχεται να διαφέρουν ανάλογα με τον τρόπο ενσωμάτωσης του υδατογραφήματος. Τα επιπεδοποιημένα ή σκαναρισμένα υδατογραφήματα δεν μπορούν πάντα να αφαιρεθούν αυτόματα.',
