  'faq.header': 'Câu hỏi thường gặp',
  'faq.q1': 'Sử dụng Doczen có miễn phí không?',
  'faq.a1': 'Có! Doczen hoàn toàn miễn phí để sử dụng. Tất cả các công cụ PDF đều có sẵn mà không có bất kỳ chi phí ẩn nào.',
  'faq.q2': 'Tệp của tôi có an toàn không?',
  'faq.a2': 'Tất nhiên rồi. Tất cả các tệp đều được mã hóa trong quá trình tải lên và tự động xóa khỏi máy chủ của chúng tôi sau 24 giờ. Chúng tôi không bao giờ chia sẻ dữ liệu của bạn.',
  'faq.q3': 'Kích thước tệp nào được hỗ trợ?',
