  'faq.q6': 'Điều gì xảy ra với dữ liệu của tôi?',
  'faq.a6': 'Tất cả các tệp đã tải lên sẽ tự động bị xóa khỏi máy chủ của chúng tôi trong vòng 24 giờ. Bạn cũng có thể xóa lịch sử của mình một cách thủ công bất kỳ lúc nào.',
