  'footer.terms': 'Điều khoản dịch vụ', 'footer.copyright': 'Toàn bộ quyền được bảo lưu.', 'footer.builtWith': 'Được xây dựng với ❤️ dành cho tài liệu PDF', 'about.title': 'Giới thiệu về Doczen',
  'about.p1': 'Doczen là một trình chỉnh sửa PDF trực tuyến miễn phí và mạnh mẽ được thiết kế để giúp việc quản lý tài liệu trở nên đơn giản và dễ tiếp cận cho mọi người. Cho dù bạn cần gộp, tách, nén, chuyển đổi hay chỉnh sửa PDF, Doczen cung cấp tất cả các công cụ bạn cần ngay trong trình duyệt của mình — không cần tải xuống, không cần cài đặt.',
  'about.p2': 'Sứ mệnh của chúng tôi là bình dân hóa việc chỉnh sửa PDF bằng cách cung cấp một bộ công cụ toàn diện hoàn toàn miễn phí để sử dụng. Chúng tôi tin rằng việc quản lý tài liệu thiết yếu không đòi hỏi các gói đăng ký phần mềm đắt đỏ.',
  'about.p3': 'Mỗi công cụ trên Doczen đều được xây dựng bằng các công nghệ web hiện đại để đảm bảo xử lý nhanh chóng, an toàn và đáng tin cậy. Quyền riêng tư của bạn là ưu tiên hàng đầu của chúng tôi — tất cả các tệp đều được mã hóa trong quá trình tải lên và tự động xóa khỏi máy chủ của chúng tôi trong vòng 24 giờ.',
